import java.io.*;
import java.util.*;

public class CutletVariant3 {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int[][] segments = new int[k][2];

        for (int i = 0; i < k; i++) {
            segments[i][0] = sc.nextInt();
            segments[i][1] = sc.nextInt();
        }

        Arrays.sort(segments, (a, b) -> a[0] - b[0]);

        List<int[]> merged = new ArrayList<>();
        int index = 0;
        while (index < k) {
            int start = segments[index][0];
            int end = segments[index][0];
            int j = index;
            while (j < k && segments[j][0] <= end) {
                end = Math.max(end, segments[j][1]);
                j++;
            }
            merged.add(new int[]{start, end});
            index = j;
        }

        k = merged.size();
        int[] lengths = new int[k];
        int[] deltas = new int[k];
        int[][] segs = new int[k][2];

        for (int i = 0; i < k; i++) {
            segs[i] = merged.get(i);
        }

        for (int i = 0; i < k; i++) {
            lengths[i] = segs[i][1] - segs[i][0];
            if (i < k - 1) {
                deltas[i] = segs[i + 1][0] - segs[i][1];
            } else {
                deltas[i] = 2 * n - segs[i][1];
            }
        }

        int[][][] dp = new int[2][k + 1][2 * n + 1];
        for (int[][] layer : dp) {
            for (int[] row : layer) {
                Arrays.fill(row, n);
            }
        }

        dp[0][k][n] = 0;
        dp[1][k][n] = 0;

        RMQ[] rmqs = {new RMQ(dp[0][k]), new RMQ(dp[1][k])};

        for (int i = k - 1; i >= 0; i--) {
            for (int j = 0; j <= 2 * n; j++) {
                int val0 = (j + lengths[i] + deltas[i] <= 2 * n) ? dp[0][i + 1][j + lengths[i] + deltas[i]] : n;
                int val1 = dp[1][i + 1][j];

                dp[0][i][j] = Math.min(val0, 1 + rmqs[1].min(j, Math.min(j + lengths[i], 2 * n)));
                if (j + deltas[i] <= 2 * n) {
                    int candidate1 = 1 + rmqs[0].min(j + deltas[i], Math.min(j + lengths[i] + deltas[i], 2 * n));
                    dp[1][i][j] = Math.min(val1, candidate1);
                } else {
                    dp[1][i][j] = val1;
                }

                if (j + deltas[i] <= 2 * n) {
                    int candidate2 = 2 + rmqs[0].min(j + deltas[i], Math.min(j + lengths[i] + deltas[i], 2 * n));
                    dp[0][i][j] = Math.min(dp[0][i][j], candidate2);
                }

                int candidate3 = 2 + rmqs[1].min(j, Math.min(j + lengths[i], 2 * n));
                dp[1][i][j] = Math.min(dp[1][i][j], candidate3);
            }
            rmqs[0] = new RMQ(dp[0][i]);
            rmqs[1] = new RMQ(dp[1][i]);
        }

        int answer = dp[1][0][0];
        if (answer == n) {
            System.out.println("Hungry");
        } else {
            System.out.println("Full");
            System.out.println(answer);
        }
    }

    static class RMQ {
        int size, log;
        int[][] table;

        public RMQ(int[] array) {
            size = array.length;
            log = Integer.numberOfTrailingZeros(Integer.highestOneBit(size)) + 1;
            table = new int[log][size];
            System.arraycopy(array, 0, table[0], 0, size);
            for (int i = 1; i < log; i++) {
                for (int j = 0; j + (1 << i - 1) < size; j++) {
                    table[i][j] = Math.min(table[i - 1][j], table[i - 1][j + (1 << i - 1)]);
                }
            }
        }

        public int min(int a, int b) {
            int length = b - a + 1;
            int z = Integer.numberOfTrailingZeros(Integer.highestOneBit(length));
            return Math.min(table[z][a], table[z][b - (1 << z) + 1]);
        }
    }
}
